class _CopyToModelParallelRegion(torch.autograd.Function):   # f
    @staticmethod
    def forward(ctx, input_, group):
        ctx.group = group
        return input_                      # identity
    @staticmethod
    def backward(ctx, grad_output):
        return _reduce(grad_output, ctx.group), None   # all-reduce

class _ReduceFromModelParallelRegion(torch.autograd.Function):  # g
    @staticmethod
    def forward(ctx, input_, group):
        return _reduce(input_, group)      # all-reduce
    @staticmethod
    def backward(ctx, grad_output):
        return grad_output, None           # identity
